    "description": "안녕하세요! 경기도 고양시 일산서구에 위치한 자동차 전장 전문점 **12V Story(12V스토리)**입니다. 오늘 소개해 드릴 작업은 기아 포르테 우측 사이드미러 폴딩불량 수리 입니다. 사이드미러 접이 버튼을 누르면 모터 돌아가는 소리는 들리는데, 정작 사이드미러는 접히지 않는 증상! 이런 경우 사이드미러 전체를 교체해야 한다고 생각하시는 분들도 많으실 텐데요. 실제로는 내부 폴딩기어가 파손되어 발생하는 경우도 있습니다. 이번 포르테 차량 역시 내부 기어 파손이 확인되어 폴딩기어 교체 작업을 진행했습니다. 12볼트스토리 채널홈을 폰으로 접속해보세요. 🔧 포르테 우측 사이드미러 폴딩불량 증상 이번에 입고된 차량은 기아 포르테입니다. 운전석이 아닌 조수석(우측) 사이드미러에 폴딩불량 이 발생했습니다. 증상은 다음과 같습니다.",
